const destinations=document.getElementById('destinations');
if(destinations){destinations.innerHTML=['Goa','Himachal','Meghalaya','Rajasthan','North East'].map((name,i)=>`<article class="destination"><div class="landscape" role="img" aria-label="Illustrative Indian destination landscape"><span>0${i+1} / EXPLORE INDIA</span></div><p class="destination-type">HOSTED GROUP TRIP</p><h4>${name}</h4><p class="trip-price">From <b>${tripPrice(name)}</b> <span>/ traveller</span></p><p>Dates, captain and final payable amount confirmed before booking.</p>${name==='Himachal'?'<a class="trip-link trip-action" href="himachal.html">Explore Himachal →</a>':`<button class="trip-action trip-button" type="button" data-trip="${name}">Explore ${name} →</button><p class="trip-status" role="status"></p>`}</article>`).join('');destinations.addEventListener('click',e=>{const button=e.target.closest('[data-trip]');if(button)button.nextElementSibling.textContent=`${button.dataset.trip} trip details are coming soon.`;});}
const bookButtons=document.querySelectorAll('[data-book]');if(bookButtons.length){bookButtons.forEach(button=>button.addEventListener('click',()=>document.getElementById('review').showModal()));document.getElementById('close-review').addEventListener('click',()=>document.getElementById('review').close());}
